      if (!user || !user.id) return reply({ error: "Sign in required." }, 401);
      const api = client.asServiceRole.entities;
      const members = await api.TeamMember.list("id", MAX_LIST_LIMIT, 0);
      const linked = members.filter((m) => Array.isArray(m.auth_user_ids) && m.auth_user_ids.includes(user.id));
      if (linked.length > 1) return reply({ error: "This sign-in is linked to more than one person and needs review." }, 409);
      if (linked.length === 0) return reply({ error: "This sign-in has no to-do access." }, 403);
