      if (caller.active !== true) return reply({ error: "This person is inactive." }, 403);
      const ownerByEmail = isOwner(user) === true;
      if (ownerByEmail && caller.member_key !== "gabriel") return reply({ error: "Owner account link needs review." }, 409);
